class Solution {
public:
    bool find132pattern(vector<int>& nums) {
        int n = nums.size();
        if (n < 3) return false;

        int nums_k = INT_MIN;
        vector<int> st;

        for (int i = n - 1; i >= 0; --i) {
            if (nums[i] < nums_k) {
                return true;
            }
            while (!st.empty() && st.back() < nums[i]) {
                nums_k = st.back();
                st.pop_back();
            }
            st.push_back(nums[i]);
        }

        return false;
    }
};
